style.css:
@-moz-document url-prefix("https://teams.microsoft.com/") {
body, .app, .main-content {
    background: linear-gradient(180deg, #ffe6eb 0%, #fffafc 100%) !important;
  }

  .app-bar, .top-bar {
    background: linear-gradient(90deg, #ffb6c1, #ffc8dd) !important;
    color: white !important;
    border-bottom: 2px solid #e598a3 !important;
  }

  button, .ts-btn, .app-bar button {
    background: #ffb6c1 !important;
    border-radius: 12px !important;
    color: white !important;
    border: none !important;
    transition: background 0.3s ease !important;
  }

  button:hover, .ts-btn:hover {
    background: #e598a3 !important;
  }

  a, .link, .tab {
    color: #e598a3 !important;
  }

  .tab:hover {
    color: #ffb6c1 !important;
  }

  .message-body, .message-content {
    background-color: #ffe6eb !important;
    border-radius: 12px !important;
    padding: 6px 10px !important;
    color: #5a4a4a !important;
  }

  .teams-left-rail {
    background-color: #ffc8dd !important;
  }

  /* Scrollbars */
  ::-webkit-scrollbar { width: 10px; }
  ::-webkit-scrollbar-track { background: #ffe6eb; }
  ::-webkit-scrollbar-thumb { background: #ffb6c1; border-radius: 10px; }
  ::-webkit-scrollbar-thumb:hover { background: #e598a3; }
}
